import { readFile, writeFile, mkdir, rm } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import fg from 'fast-glob'
import { parse as parseYaml } from 'yaml'
import { splitFrontmatter } from './lint.js'
import { DocsIndexFile, GuardrailsFile, VersionsFile, type DocsIndex, type Guardrail, type Versions } from './schema.js'

export interface RenderOptions {
  contentDir: string
  mcpOut: string
  skillRefsOut: string
  version: string
}

/** Renders every generated file as path → content, without touching the disk. Paths are `join(mcpOut | skillRefsOut, name)`. */
export async function renderAll(opts: RenderOptions): Promise<Map<string, string>> {
  const { contentDir, mcpOut, skillRefsOut, version } = opts
  const read = (file: string) => readFile(join(contentDir, file), 'utf8')
  const out = new Map<string, string>()

  // MCP snapshot: content/ verbatim, plus JSON forms of the two YAML files.
  for (const file of (await fg('**/*', { cwd: contentDir, onlyFiles: true })).sort()) {
    out.set(join(mcpOut, file), await read(file))
  }
  const guardrails = GuardrailsFile.parse(parseYaml(await read('guardrails.yaml')))
  const docsIndex = DocsIndexFile.parse(parseYaml(await read('docs-index.yaml')))
  out.set(join(mcpOut, 'guardrails.json'), json(guardrails))
  out.set(join(mcpOut, 'docs-index.json'), json(docsIndex))

  // Skill references.
  const header = `<!-- generated by packages/sync from @bsv/mcp content v${version}; do not edit; verified dates inside -->`
  const ref = (name: string, body: string) => out.set(join(skillRefsOut, name), `${header}\n\n${body.trim()}\n`)
  const versions = VersionsFile.parse(JSON.parse(await read('versions.json')))
  ref('facts.md', await renderFacts(contentDir, docsIndex))
  ref('guardrails.md', renderGuardrails(guardrails, versions.verified))
  ref('stack.md', renderStack(versions))
  for (const name of ['custody-shapes.md', 'threat-model.md']) ref(name, copyWithVerified(await read(name), name))
  return out
}

/**
 * Writes each file whose content differs (check=false) or only reports it (check=true). Files inside
 * `ownedDirs` that the map does not contain are stale: reported, and removed when writing.
 * Returns the differing paths, sorted.
 */
export async function writeOrCheck(files: Map<string, string>, check: boolean, ownedDirs: string[] = []): Promise<string[]> {
  const differing: string[] = []
  for (const [path, content] of [...files].sort(([a], [b]) => a.localeCompare(b))) {
    const current = existsSync(path) ? await readFile(path, 'utf8') : undefined
    if (current === content) continue
    differing.push(path)
    if (!check) {
      await mkdir(dirname(path), { recursive: true })
      await writeFile(path, content)
    }
  }
  for (const dir of ownedDirs) {
    if (!existsSync(dir)) continue
    for (const file of await fg('**/*', { cwd: dir, onlyFiles: true, dot: true })) {
      const path = join(dir, file)
      if (files.has(path)) continue
      differing.push(path)
      if (!check) await rm(path)
    }
  }
  return differing.sort((a, b) => a.localeCompare(b))
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`
}

interface Doc {
  title: string
  verified: string
  body: string
}

function parseDoc(text: string, file: string): Doc {
  const { data, body } = splitFrontmatter(text)
  const fm = (data ?? {}) as Record<string, unknown>
  if (typeof fm.title !== 'string' || typeof fm.verified !== 'string') throw new Error(`${file}: frontmatter needs title and verified`)
  return { title: fm.title, verified: fm.verified, body: body.trim() }
}

/** Applies `fn` to each line outside fenced code blocks. */
function mapProse(body: string, fn: (line: string) => string | undefined): string {
  let fence: string | undefined
  const lines: string[] = []
  for (const line of body.split('\n')) {
    const marker = /^\s*(`{3,}|~{3,})/.exec(line)?.[1]
    if (marker && (fence === undefined || marker.startsWith(fence))) {
      fence = fence === undefined ? marker : undefined
      lines.push(line)
      continue
    }
    const mapped = fence === undefined ? fn(line) : line
    if (mapped !== undefined) lines.push(mapped)
  }
  return lines.join('\n')
}

/** Drops the leading H1 (the document title) and returns the rest. */
function withoutH1(body: string): string {
  if (!/^# /.test(body)) return body
  const nl = body.indexOf('\n')
  return nl === -1 ? '' : body.slice(nl + 1).trim()
}

async function renderFacts(contentDir: string, docsIndex: DocsIndex): Promise<string> {
  const sections = ['# BSV facts', 'Every fact file from `content/facts/`, each under its title with the date it was last verified.']
  for (const file of (await fg('facts/*.md', { cwd: contentDir })).sort()) {
    const doc = parseDoc(await readFile(join(contentDir, file), 'utf8'), file)
    const demoted = mapProse(withoutH1(doc.body), (line) => (/^#{1,5} /.test(line) ? `#${line}` : line))
    sections.push(`## ${doc.title}`, `verified: ${doc.verified}`, demoted)
  }
  sections.push(
    '## Docs links',
    'Every docs page by stable id, on each docs host in order of preference (append `.md` for the Markdown form), plus its legacy URL where one exists. The `docs_url` tool picks the first that answers.',
    Object.keys(docsIndex.ids)
      .sort()
      .map((id) => {
        const { path, title, legacy } = docsIndex.ids[id]
        const urls = docsIndex.hosts.map((host) => `${host}${path}`).join(', ')
        return `- ${title} (\`${id}\`): ${urls}${legacy ? `; legacy ${legacy}` : ''}`
      })
      .join('\n'),
  )
  return sections.filter(Boolean).join('\n\n')
}

function copyWithVerified(text: string, file: string): string {
  const doc = parseDoc(text, file)
  const verified = `verified: ${doc.verified}`
  const h1 = /^# .*/.exec(doc.body)?.[0]
  return [h1, verified, withoutH1(doc.body)].filter(Boolean).join('\n\n')
}

function renderGuardrails(guardrails: Guardrail[], verified: string): string {
  const parts = [
    '# Guardrails',
    `verified: ${verified}`,
    `Rules ${guardrails[0]?.id ?? ''}..${guardrails.at(-1)?.id ?? ''} from \`content/guardrails.yaml\`. Shape A is a user-side BRC-100 wallet, shape B an app-side server wallet (see \`custody-shapes.md\`). Detect: \`static\` rules are flagged by the \`check_guardrails\` tool, \`manual\` rules are a review checklist, \`contract\` rules apply to contract code and are reviewed by hand.`,
    '## Rules',
  ]
  for (const g of guardrails) {
    parts.push(
      `### ${g.id} ${g.title}`,
      [
        `- **Rule:** ${g.rule}`,
        `- **Why:** ${g.why}`,
        `- **Shape:** ${g.shape}`,
        `- **Detect:** ${g.detect}`,
        `- **Severity:** ${g.severity}`,
        `- **Refs:** ${g.refs.length ? g.refs.map((r) => `\`${r}\``).join(', ') : 'none'}`,
      ].join('\n'),
    )
  }
  return parts.join('\n\n')
}

function cell(value: string | undefined): string {
  return (value ?? '').replace(/\|/g, '\\|')
}

function table(head: string[], rows: string[][]): string {
  return [head, head.map(() => '---'), ...rows].map((r) => `| ${r.map(cell).join(' | ')} |`).join('\n')
}

function renderStack(v: Versions): string {
  const parts = [
    '# Stack',
    `verified: ${v.verified}`,
    'Pinned versions from `content/versions.json`. Each row carries the date it was last verified.',
    '## npm packages',
    table(
      ['package', 'pinned', 'verified', 'note'],
      Object.entries(v.packages).map(([name, p]) => [`\`${name}\``, p.pinned, p.verified, p.note ?? '']),
    ),
    '## Git sources',
    table(
      ['name', 'repo', 'branch', 'commit', 'version', 'verified', 'npm'],
      Object.entries(v.git).map(([name, g]) => [
        name,
        `\`${g.repo}\``,
        g.branch,
        `\`${g.commit}\``,
        g.version,
        g.verified,
        g.npmVersion === undefined ? '' : `${g.npmVersion}${g.npmUnsafe ? ' (unsafe; do not use)' : ''}`,
      ]),
    ),
    '## Services',
  ]
  for (const [name, s] of Object.entries(v.services)) {
    parts.push(
      `### ${name}`,
      `Version ${s.version}, verified ${s.verified}.`,
      table(['network', 'hosts'], Object.entries(s.hosts).map(([network, hosts]) => [network, hosts.map((h) => `\`${h}\``).join(', ')])),
    )
  }
  parts.push('## Runtime', table(['runtime', 'requirement'], Object.entries(v.runtime).map(([name, req]) => [name, `\`${req}\``])))
  return parts.join('\n\n')
}
